#r "nuget: MSBuild.StructuredLogger, 2.2.370"
using Microsoft.Build.Logging.StructuredLogger;

var build = BinaryLog.ReadBuild("build.binlog");

// Find all failed targets and projects
var results = build.FindChildrenRecursive<Microsoft.Build.Logging.StructuredLogger.Target>()
    .Where(t => !t.Succeeded)
    .Select(t => new { Target = t.Name, Project = t.GetNearestParent<Project>()?.Name })
    .Distinct()
    .ToList();

Console.WriteLine("Failed targets:");
foreach (var r in results)
    Console.WriteLine($"  {r.Project} -> {r.Target}");

// Check if Api.csproj had build errors or just dependency failures
Console.WriteLine("\nApi.csproj errors:");
var apiErrors = build.FindChildrenRecursive<Error>()
    .Where(e => e.GetNearestParent<Project>()?.Name == "Api.csproj");
foreach (var e in apiErrors)
    Console.WriteLine($"  {e.Code}: {e.Text}");
if (!apiErrors.Any())
    Console.WriteLine("  (none - likely cascading from Services.csproj failure)");
EOF
